<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$first=trim((string)($_POST['first_name']??''));$last=trim((string)($_POST['last_name']??''));$sex=(string)($_POST['sex']??'');$dob=trim((string)($_POST['date_of_birth']??''));$national=trim((string)($_POST['national_id']??''));$form=filter_var($_POST['intended_form']??null,FILTER_VALIDATE_INT);$year=filter_var($_POST['entry_year']??null,FILTER_VALIDATE_INT);$stream=trim((string)($_POST['stream_preference']??''));$previous=trim((string)($_POST['previous_school']??''));$guardian=trim((string)($_POST['guardian_name']??''));$relationship=(string)($_POST['guardian_relationship']??'');$phone=trim((string)($_POST['guardian_phone']??''));$email=strtolower(trim((string)($_POST['guardian_email']??'')));$address=trim((string)($_POST['address']??''));$relations=['Parent','Legal guardian','Grandparent','Other relative','Other'];$dobValue=$dob===''?null:DateTimeImmutable::createFromFormat('!Y-m-d',$dob);$dateErrors=$dob===''?false:DateTimeImmutable::getLastErrors();$badDob=$dob!==''&&($dobValue===false||$dobValue->format('Y-m-d')!==$dob||($dateErrors!==false&&($dateErrors['warning_count']||$dateErrors['error_count']))||$dob>date('Y-m-d'));
if($first===''||strlen($first)>80||$last===''||strlen($last)>80||!in_array($sex,['F','M'],true)||$badDob||strlen($national)>30||$form===false||$form<1||$form>6||$year===false||$year<date('Y')||$year>2100||strlen($stream)>20||strlen($previous)>180||$guardian===''||strlen($guardian)>160||!in_array($relationship,$relations,true)||!preg_match('/^[+0-9()\s-]{7,30}$/',$phone)||strlen($email)>160||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||strlen($address)>1000){$_SESSION['error']='Check the applicant, intended form/year and guardian contact details.';header('Location: ../?page=admissions&new=1');exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO admission_applications(application_code,first_name,last_name,sex,date_of_birth,national_id,intended_form,entry_year,stream_preference,previous_school,guardian_name,guardian_relationship,guardian_phone,guardian_email,address,submitted_by) VALUES(NULL,:first,:last,:sex,:dob,:national,:form,:year,:stream,:previous,:guardian,:relationship,:phone,:email,:address,:user)");$q->execute(['first'=>$first,'last'=>$last,'sex'=>$sex,'dob'=>$dob?:null,'national'=>$national?:null,'form'=>$form,'year'=>$year,'stream'=>$stream?:null,'previous'=>$previous?:null,'guardian'=>$guardian,'relationship'=>$relationship,'phone'=>$phone,'email'=>$email?:null,'address'=>$address?:null,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();$code='APP-'.(int)$year.'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$q=$pdo->prepare('UPDATE admission_applications SET application_code=:code WHERE id=:id');$q->execute(['code'=>$code,'id'=>$id]);$q=$pdo->prepare("INSERT INTO admission_status_history(application_id,from_status,to_status,notes,changed_by) VALUES(:id,NULL,'Submitted','Application registered',:user)");$q->execute(['id'=>$id,'user'=>$user['id']]);audit_log('admissions.application_submitted','admission_applications',$id,['application_code'=>$code,'intended_form'=>$form,'entry_year'=>$year]);$pdo->commit();$_SESSION['notice']='Application '.$code.' registered.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Admission submission failed: '.$e->getMessage());$_SESSION['error']='Could not register the application. Please review the details and try again.';}header('Location: ../?page=admissions');exit;
